// Lo único que se interpola en la consulta es el ID, así que acá se exige que
// sea solo dígitos. Cualquier otra cosa corta la corrida sin tocar SQL Server.
const cuerpo = $input.first().json.body ?? {};
const id = String(cuerpo.id ?? '').trim();
if (!/^\d{5,12}$/.test(id)) {
  throw new Error('ID de viaje inválido: tiene que ser un número de 5 a 12 dígitos.');
}
return [{ json: { id } }];

// Una fila por movimiento, con los datos del viaje repetidos en cada una.
// Se devuelve un solo objeto: el viaje y su historial en orden cronológico.
const filas = $input.all().map((item) => item.json);
const primera = filas[0] ?? {};

if (!primera.IdViaje) {
  return [{ json: { encontrado: false, id: String(primera.IdConsultado ?? '') } }];
}

const visitado = (valor) => valor === true || valor === 1 || valor === '1';

return [{
  json: {
    encontrado: true,
    id: String(primera.IdViaje),
    viaje: {
      estado_actual: primera.EstadoActual ?? null,
      tienda: primera.Tienda ?? null,
      id_modalidad: primera.IdModalidad ?? null,
      id_localidad: primera.IdLocalidad ?? null,
      poligono: primera.Poligono ?? null,
      fecha_programado: primera.FechaProgramado ?? null,
      visitas: primera.Visitas ?? null,
    },
    historial: filas
      .filter((fila) => fila.Fecha)
      .map((fila) => ({
        fecha: fila.Fecha,
        estado: fila.Estado ?? null,
        repartidor: fila.Repartidor ?? null,
        visitado: visitado(fila.VisitadoMotoboy),
        responsable: fila.Responsable ?? null,
        foto: fila.Foto ?? null,
      })),
  },
}];
